import { Statement } from '../types/statement';
import { StatementInteraction } from '../types/statement-interactions';
import StatementVerbHelper from './statement/verb';

export default class StatementInteractionHelper {
  /**
   * Initiates interactions from the statements
   *
   * @param statements - A list of Statement objects
   * @returns An array of GroupedDataInteraction objects
   */
  public static initiateStatementInteractions(
    statements: Statement[],
  ): StatementInteraction[] {
    const interactionUrls: Set<string> = new Set();

    // Take only the statements with the initialized verb
    const initializedStatements = StatementVerbHelper.getStatementsByInitializedVerb(statements);

    const statementInteractions = initializedStatements
      .reduce<StatementInteraction[]>((interactions, statement) => {
      const objectId = statement.object.id;
      // Filter out duplicate interaction URLs
      if (!interactionUrls.has(objectId)) {
        interactionUrls.add(objectId);

        interactions.push({
          url: objectId,
          name: statement.object.definition?.name ?? {},
        });
      }
      return interactions;
    }, []);

    return statementInteractions;
  }
}
