import { Duration } from 'luxon';

import StatementInteractionHelper from '../helpers/interaction/statement-interaction';
import StatementVerbHelper from '../helpers/statement/verb';
import { IGroupedDataInteraction } from '../interfaces/IGroupedDataInteraction';
import { CompletedStatus } from '../types/completed-status';
import { InteractionAnswer } from '../types/interactionAnswers';
import { Choices, Statement } from '../types/statement';
import { SuccessStatus } from '../types/success-status';

export default class GroupedDataInteraction implements IGroupedDataInteraction {
  /** The completedStatus of the interaction */
  public get completedStatus(): CompletedStatus | undefined {
    return this.#completedStatus;
  }

  /** The key of the interaction */
  public get key(): number {
    return this.#key;
  }

  /** The key of the module */
  public get module(): number | undefined {
    return this.#module;
  }

  /** The name of the interaction */
  public get name(): string {
    return this.#name;
  }

  /** A list of statement indexes */
  public get statementIdxs(): number[] {
    return this.#statementIdxs;
  }

  /** A list of sub interactions */
  public get subInteractions(): GroupedDataInteraction[] {
    return this.#subInteractions;
  }

  /** The successStatus of the interaction */
  public get successStatus(): SuccessStatus | undefined {
    return this.#successStatus;
  }

  /** The url of the interaction */
  public get url(): string {
    return this.#url;
  }

  #completedStatus: CompletedStatus | undefined;

  #key: number;

  #module: number | undefined;

  #name: string;

  #statementIdxs: number[];

  #subInteractions: GroupedDataInteraction[];

  #successStatus: SuccessStatus | undefined;

  #url: string;

  /**
   * Constructor for GroupedDataInteraction
   *
   * @param [completedStatus] - The completedStatus of the interaction
   * @param key - The key of the interaction
   * @param [module] - The key of the module
   * @param name - The name of the interaction
   * @param statementIdxs - A list of statement indexes
   * @param [subInteractions] - The sub-interactions of the interaction
   * @param [successStatus] - The successStatus of the interaction
   * @param url - The url of the interaction
   */
  constructor({
    completedStatus, key, module, name, statementIdxs, subInteractions, successStatus,
    url,
  }: {
    completedStatus?: CompletedStatus;
    key: number;
    module?: number;
    name: string;
    statementIdxs: number[];
    subInteractions?: GroupedDataInteraction[];
    successStatus?: SuccessStatus;
    url: string;
  }) {
    this.#completedStatus = completedStatus;
    this.#key = key;
    this.#module = module;
    this.#name = name;
    this.#statementIdxs = statementIdxs;
    this.#subInteractions = subInteractions ?? [];
    this.#successStatus = successStatus;
    this.#url = url;
  }

  /**
   * Deep copy of the GroupedDataInteraction
   *
   * @returns A new GroupedDataInteraction object copied by value instead of reference
   */
  public deepCopy(): GroupedDataInteraction {
    const subInteractions = this.#subInteractions.map((interaction) => interaction.deepCopy());
    return new GroupedDataInteraction({
      completedStatus: this.#completedStatus,
      key: this.#key,
      module: this.#module,
      name: this.#name,
      statementIdxs: this.#statementIdxs,
      subInteractions,
      successStatus: this.#successStatus,
      url: this.#url,
    });
  }

  /**
   * Add statement indexes to the interaction
   *
   * @param statementId - The statement index to add
   */
  public addStatement(statementId: number) {
    this.#statementIdxs.push(statementId);
  }

  /**
   * Sets the statement indexes to the interaction, this overrites the current statement indexes
   *
   * @param statementIdxs - An array of statement indexes
   */
  public setStatementIdxs(statementIdxs: number[]) {
    this.#statementIdxs = statementIdxs;
  }

  /**
   * Add sub interactions to the interaction
   *
   * @param interaction - A GroupedDataInteraction object
   */
  public addSubInteraction(interaction: GroupedDataInteraction) {
    this.#subInteractions.push(interaction);
  }

  /**
   * Get the score of the statements from the interaction
   *
   * @param statements - A list of Statement objects
   * @returns The score of the interaction
   */
  public getScore(statements: Statement[]): number {
    const usedStatements = this.#statementIdxs.map((statementId) => statements[statementId]);
    return StatementVerbHelper.getStatementsWithScoreExtension(usedStatements).map(
      (statement) => statement.result?.score?.scaled ?? 0,
    )[0]; // TODO: This returns the last score. This should become configurable
  }

  /**
   * Get the initializations from the interaction
   *
   * @param statements - A list of Statement objects
   * @returns The number of initializations
   */
  public getInitializations(statements: Statement[]): number {
    const usedStatements = this.#statementIdxs.map((statementId) => statements[statementId]);
    return StatementVerbHelper.getStatementsByInitializedVerb(usedStatements).length;
  }

  /**
   * Get the duration from the interaction
   *
   * @param statements - A list of Statement objects
   * @returns The duration of the interaction
   */
  public getDuration(statements: Statement[]): number {
    const usedStatements = this.#statementIdxs.map((statementId) => statements[statementId]);
    const scoredStatements = StatementVerbHelper.getStatementsWithScoreExtension(usedStatements);

    return scoredStatements.map(
      (statement) => Duration.fromISO(statement.result?.duration ?? '').as('seconds'),
    )[0]; // TODO: This returns the last duration. This should become configurable;
  }

  /**
   * Get the answer options from the interaction
   *
   * @param statements - A list of Statement objects
   * @returns The answer options from the interaction
   */
  public getInteractionAnswerOptions(statements: Statement[]): InteractionAnswer {
    const usedStatements = this.#statementIdxs.map((statementId) => statements[statementId]);
    const answeredStatements = StatementVerbHelper.getStatementsByAnsweredVerb(usedStatements);

    return {
      type: 'choices',
      answer: {
        choices: Array.from(new Set(
          answeredStatements.flatMap(
            (statement) => statement.object?.definition?.choices?.map((choice) => choice.id) ?? [],
          ),
        )),
        choicesResponse: answeredStatements.reduce(
          (acc, statement) => acc.set(
            statement.result?.response,
            (acc.get(statement.result?.response) || 0) + 1,
          ),
          new Map<string | undefined, number>(),
        ),
        correctResponsesPattern: answeredStatements.flatMap(
          (statement) => statement.object?.definition?.correctResponsesPattern?.map(
            (responsePattern) => responsePattern,
          ) ?? [],
        ),
        nrOfAttempts: answeredStatements.length,
      },
    };
  }

  /**
    * Update the interaction with new statement indexes and set the completion status
    *
    * @param allStatementIdxs - A list of all statement indexes
    * @param statements - A list of Statement objects
    */
  public updateInteraction(
    allStatementIdxs: number[],
    statements: Statement[],
  ) {
    // Filter the statementIdxs
    const statementIdxs = this.#statementIdxs.filter(
      (statementId) => allStatementIdxs.includes(statementId),
    );
    this.setStatementIdxs(statementIdxs);

    console.log('statements', statementIdxs.map((statementId) => statements[statementId]));

    // Set the completion status
    const hasPassed = StatementInteractionHelper.hasPassed({ statements, statementIdxs });
    const hasCompleted = StatementInteractionHelper.hasCompleted({ statements, statementIdxs });
    const hasStarted = StatementInteractionHelper.hasStarted({ statements, statementIdxs });

    this.setCompletedStatus({ hasPassed, hasCompleted, hasStarted });
  }

  /**
     * Sets the completed status and the succes status of the interaction
     *
     * @param hasPassed - A boolean indicating if the interaction has passed
     * @param hasCompleted - A boolean indicating if the interaction has been completed
     * @param hasStarted - A boolean indicating if the interaction has been started
     */
  private setCompletedStatus({ hasPassed, hasCompleted, hasStarted }: {
    hasPassed: boolean;
    hasCompleted: boolean;
    hasStarted: boolean;
  }) {
    if (hasPassed) {
      this.#completedStatus = 'completed';
      this.#successStatus = 'passed';
    } else if (hasCompleted) {
      this.#completedStatus = 'completed';
      this.#successStatus = 'failed';
    } else if (hasStarted) {
      this.#completedStatus = 'incomplete';
    }
  }
}
