import IXTResult from '../interfaces/IXTResult';
import { EXTENSION_URL_TRACKING_STATE } from '../types/extension';
import { Statement } from '../types/statement';
import { SuccessStatus } from '../types/success-status';
import {
  ExternalTrackingState, MatchOption, toTrackingState, TrackingInteraction, TrackingState,
} from '../types/tracking-state';
import { XTInteraction } from '../types/xt-interaction';
import { XTInteractionStatus } from '../types/xt-interaction-status';
import { XTMode } from '../types/xt-mode';
import { XTScoreMode } from '../types/xt-score-mode';
import { XTSubInteraction } from '../types/xt-subinteraction';

export default class XTResults implements IXTResult {
  /** The average score */
  public get averageScore(): number {
    return this.#averageScore;
  }

  /** The completed status */
  public get completedStatus(): XTInteractionStatus {
    return this.#completedStatus;
  }

  /** The completion */
  public get completion(): number {
    return this.#completion;
  }

  /** A list of interactions */
  public get interactions(): XTInteraction[] {
    return this.#interactions;
  }

  /** The mode */
  public get mode(): XTMode {
    return this.#mode;
  }

  /** The number of questions */
  public get nrOfQuestions(): number {
    return this.#nrOfQuestions;
  }

  /** The score */
  public get score(): number {
    return this.#score;
  }

  /** The score mode */
  public get scoreMode(): XTScoreMode {
    return this.#scoreMode;
  }

  /** The start date */
  public get start(): Date {
    return this.#start;
  }

  /** The success status */
  public get successStatus(): SuccessStatus {
    return this.#successStatus;
  }

  /** The total duration */
  public get totalDuration(): number {
    return this.#totalDuration;
  }

  #averageScore: number;

  #completedStatus: XTInteractionStatus;

  #completion: number;

  #interactions: XTInteraction[] = [];

  #mode: XTMode; // Currently unused

  #nrOfQuestions: number;

  #score: number = 0;

  #scoreMode: XTScoreMode;

  #start: Date;

  #successStatus: SuccessStatus;

  #totalDuration: number;

  #trackingState: TrackingState;

  /**
   * Constructor
   *
   * @param statement - The statement to create the XTResults from
   */
  public constructor(statement: Statement) {
    // Get the tracking state from the statement result extensions
    const trackingStateExtension = statement.result?.extensions[EXTENSION_URL_TRACKING_STATE];
    if (trackingStateExtension === undefined) throw new Error('No tracking state found');

    // Convert the json to an internal tracking state object
    this.#trackingState = toTrackingState(
      JSON.parse(trackingStateExtension) as ExternalTrackingState,
    );

    this.#start = this.#trackingState.start;
    this.#scoreMode = this.#trackingState.scoreMode;

    // Set the completion
    this.#completion = this.setCompletion();
    // Set the completed status
    this.#completedStatus = this.getCompletedStatus();
    // Set the success status
    this.#successStatus = this.getSuccessStatus();
    // Set the average score
    this.#averageScore = this.getRawScore();

    // Iterate over the interactions and set the XTResults values
    this.iterateInteractions();
  }

  /**
   * Iterates over the interactions to compute the XTResults values
   */
  private iterateInteractions(): void {
    let nrOfQuestions = 0;
    let totalDuration = 0;

    this.#trackingState.interactions.forEach((interaction) => {
      // Calulate the score
      this.#score += interaction.score * interaction.weighting;

      if (interaction.iaNr < 0 || interaction.nrInteractions > 0) {
        this.#interactions[nrOfQuestions] = {
          id: '',
          score: Math.round(interaction.score),
          title: interaction.iaName,
          type: interaction.iaType,
          correct: interaction.result,
          duration: Math.round(interaction.duration / 1000),
          weighting: interaction.weighting,
          subinteractions: [],
          completed: this.#trackingState.toCompletePages.find(
            (currentPageNr) => currentPageNr === interaction.pageNr,
          ) ? 'completed' : 'incomplete',
        };

        nrOfQuestions += 1;
        totalDuration += interaction.duration;
      } else {
        // If mode is 'full-results' which currently is the only mode
        this.#interactions[nrOfQuestions - 1].subinteractions.push(
          ...XTResults.getSubinteractions(interaction),
        );
      }
    });

    this.#nrOfQuestions = nrOfQuestions;
    this.#totalDuration = Math.round(totalDuration / 1000);
  }

  /**
   * Get subinteractions for interaction
   *
   * @param interaction - The interaction to get subinteractions for
   * @returns A list of subinteractions
   */
  private static getSubinteractions(interaction: TrackingInteraction): XTSubInteraction[] {
    if (interaction.iaType === 'match') {
      return (interaction.correctOptions as MatchOption[]).map((correctOption) => {
        // Create a subinteraction here for every match sub instead
        const { source, target } = correctOption;
        const correctAnswer = `${source} --> ${target}`;

        const learnerAnswer = `${source} --> ${(interaction.learnerOptions as MatchOption[]).find(
          (learnerOption) => source === learnerOption.source,
        )?.target ?? ' '}`;

        return {
          question: interaction.iaName,
          correct: interaction.result.success,
          learnerAnswer,
          correctAnswer,
        };
      });
    } if (interaction.iaType === 'text') {
      return [{
        learnerAnswer: interaction.learnerAnswers,
        correctAnswer: interaction.correctAnswers,
      }];
    } if (interaction.iaType === 'multiplechoice') {
      return [{
        learnerAnswer: interaction.learnerAnswers.join('\n'),
        correctAnswer: interaction.correctAnswers.join('\n'),
      }];
    } if (interaction.iaType === 'numeric') {
      return [{
        learnerAnswer: interaction.learnerAnswers,
        correctAnswer: '-', // Not applicable
      }];
    } if (interaction.iaType === 'fill-in') {
      return [{
        learnerAnswer: interaction.learnerAnswers,
        correctAnswer: interaction.correctAnswers,
      }];
    }
    throw new Error(`Unknown interaction type: ${interaction.iaType}`);
  }

  /**
   * Set the completion percentage based on the number of completed pages
   *
   * @returns The completion percentage
   */
  private setCompletion(): number {
    const nrCompleted = this.#trackingState.completedPages.reduce(
      (completed, completedPage) => (completedPage ? completed + 1 : completed),
      0,
    );

    if (nrCompleted !== 0) {
      return Math.round(
        (nrCompleted / this.#trackingState.completedPages.length) * 100,
      );
    }
    return 0;
  }

  /**
   * Set the completion status based on the completed pages from the tracking state
   *
   * @returns The completion status
   */
  private getCompletedStatus(): XTInteractionStatus {
    const completed = !this.#trackingState.completedPages.some((page) => !page);

    if (completed) {
      return 'completed';
    }
    if (!completed) {
      return 'incomplete';
    }
    return 'unknown';
  }

  /**
   * Set the success status based on the score and the completedStatus of the tracking state
   *
    * @returns The success status
   */
  private getSuccessStatus(): SuccessStatus {
    // Check if the page is not pages only
    if (this.#trackingState.loType !== 'pages only') {
      return this.getRawScore() >= this.#trackingState.loPassed ? 'passed' : 'failed';
    }

    // If the learning object type is pages only, return passed if the object is completed
    return this.getCompletedStatus() === 'completed' ? 'passed' : 'unknown';
  }

  /**
   * Get the raw score of the tracking state. If hte learning object type is pages
   * only, return 100 if the object is completed. Otherwise, get the score and the
   * weights of the interactions
   *
   * @returns The raw score
   */
  private getRawScore(): number {
    // If the learning object type is pages only, return 100 if the object is completed
    if (this.#trackingState.loType === 'pages only') {
      return this.getCompletedStatus() === 'completed' ? 100 : 0;
    }

    let totalScore = 0.0;
    let totalWeight = 0.0;
    this.#trackingState.interactions
      .filter((interaction) => interaction.iaNr === -1)
      .forEach((interaction) => {
        totalScore += interaction.score * interaction.weighting;
        totalWeight += interaction.weighting;
      });

    // If the total weight is 0, return 100
    if (totalWeight === 0) {
      return 100;
    }

    totalScore /= totalWeight;
    return Math.round(totalScore);
  }
}
