import { Extension } from './extension';
import { LanguageMap } from './language-map';
import { Verb } from './verb';
import { XTInteractionType } from './xt-interaction-type';

export type AccountObject = {
  homePage: string;
  name: string;
};

export type ActorType = 'Agent' | 'Group';

export type Actor = {
  objectType?: ActorType;
  name?: string;
  mbox?: string;
  mbox_sha1sum?: string;
  openid?: string;
  account?: AccountObject;
};

export type Choices = {
  id: string;
  description?: LanguageMap;
};

export type ObjectDefinition = {
  name?: LanguageMap;
  description?: LanguageMap;
  type?: string;
  moreInfo?: string;
  extensions: Extension;
  choices?: Choices[];
  correctResponsesPattern?: string[];
  interactionType: XTInteractionType;
};

export type StatementObject = {
  objectType?: string;
  id: string;
  definition?: ObjectDefinition;
};

export type Score = {
  scaled?: number;
  raw?: number;
  min?: number;
  max?: number;
};

export type Result = {
  score?: Score;
  success?: boolean;
  completion?: boolean;
  response?: string;
  duration?: string;
  extensions: Extension;
};

export type ContextActivities = {
  parent?: StatementObject[];
  grouping?: StatementObject[];
  category?: StatementObject[];
  other?: StatementObject[];
};

export type StatementReference = {
  objectType: string;
  id: string;
};

export type Context = {
  registration?: string;
  instructor?: Actor;
  team?: Actor;
  contextActivities?: ContextActivities;
  revision?: string;
  platform?: string;
  language?: string;
  statement?: StatementReference;
  extensions: Extension;
};

export type Statement = {
  id?: string;
  actor: Actor;
  verb: Verb;
  object: StatementObject;
  result?: Result;
  context?: Context;
  timestamp?: string;
  stored: string;
  authority?: Actor;
  version?: string;
  attachments?: any[];
};

export class StatementValidationError extends Error {
  public constructor(message: string) {
    super(message);
    this.name = 'StatementValidationError';
  }
}

export function validateStatements(statements: Statement[]): Statement[] {
  if (!(statements instanceof Array)) {
    throw new StatementValidationError('Statements must be an array');
  }
  statements.forEach((statement) => {
    if (!('actor' in statement)) {
      throw new StatementValidationError('Statement is missing actor');
    }
  });
  return statements;
}
