import type GroupedDataInteraction from '../../grouped-data-interaction/grouped-data-interaction';
import { Statement } from '../../types/statement';
import StatementVerbHelper from '../statement/verb';

export default class InteractionHelper {
  /**
   * Get parent interaction id
   * @param interactionId - The id of the interaction
   */
  public static getParentInteractionId(interactionId: string): string {
    const segments = interactionId.split('/');
    segments.pop();
    return segments.join('/');
  }

  /**
   * Add statements to interactions
   *
   * @param statements - A list of Statement objects
   * @param interactions - A list of GroupedDataInteraction objects
   */
  public static addStatementsToInteractions(
    statements: Statement[],
    interactionHashes: Map<string, { index: number; childIndex: number | undefined }>,
    interactions: GroupedDataInteraction[],
  ) {
    statements.forEach((statement, statementId) => {
      // Get the index of the interaction
      const interactionIndex = interactionHashes.get(statement.object.id);

      if (interactionIndex?.index !== undefined) {
        if (interactionIndex.childIndex !== undefined) {
          // Get the interaction and add the statementId to the child
          interactions[interactionIndex.index]
            .subInteractions[interactionIndex.childIndex]
            .addStatement(statementId);
        } else {
          // Get the interaction and add the statementId
          interactions[interactionIndex.index].addStatement(statementId);
        }
      }
    });
  }
}
