import InverseFunctionalIdentifier from '../../inverse-functional-identifier/inverse-functional-identifier';
import { EXTENSION_URL_LEARNING_OBJECT_ID, EXTENSION_URL_MODULE } from '../../types/extension';
import { Statement } from '../../types/statement';

export default class StatementHelper {
  /**
   * Get the index of a module for the provided statement
   *
   * @param statement - A Statement object
   * @param moduleHashes - A map of module IDs to indexes
   * @param useTemplateIds - A boolean indicating whether to use template IDs
   * @returns The index of the module
   */
  public static getModuleIndex(
    statement: Statement,
    moduleHashes: Map<string, number>,
    useTemplateIds: boolean,
  ): number {
    // Use template ids to get the module index
    if (useTemplateIds) {
      const learningObjectId = statement.context?.extensions[EXTENSION_URL_LEARNING_OBJECT_ID];
      if (learningObjectId !== undefined) {
        const moduleId = moduleHashes.get(learningObjectId);
        if (moduleId !== undefined) {
          return moduleId;
        }
      } else if (statement.object?.id !== undefined) {
        const position1 = statement.object.id.indexOf('/');
        if (position1 >= 0) {
          const position2 = statement.object.id.indexOf('/', position1);
          if (position2 >= 0) {
            const id = statement.object.id.substring(0, position2);
            const moduleId = moduleHashes.get(id);
            if (moduleId !== undefined) {
              return moduleId;
            }
          } else if (moduleHashes.get(statement.object.id) !== undefined) {
            return moduleHashes.get(statement.object.id)!;
          }
        }
      }
      return -1;
    }

    // Use template mod hashes to get the module index
    const extensionModule = statement.context?.extensions[EXTENSION_URL_MODULE];
    if (extensionModule !== undefined) {
      const moduleId = moduleHashes.get(extensionModule);
      if (moduleId !== undefined) {
        return moduleId;
      }
    }

    return -1;
  }

  /**
   * Get the index of a user for the provided statement
   *
   * @param statement - A Statement object
   * @param users - A map of user IDs to indexes
   * @returns The index of the user
   */
  public static getUserIndex(statement: Statement, users: Map<string, number>): number {
    const hash = InverseFunctionalIdentifier.getHashFromStatement(statement);
    return users.get(hash) ?? -1;
  }

  /**
   * Get the index of an interaction for the provided statement
   *
   * @param statement - A Statement object
   * @param interactionHashes - A map of interaction IDs to indexes
   * @param xerteUrlLenght - The length of the Xerte URL
   * @returns The index of the interaction
   */
  public static getInteractionIndex(
    statement: Statement,
    interactionHashes: Map<string, { index: number; childIndex: number | undefined }>,
    xerteUrlLenght: number,
  ): { index: number; childIndex: number | undefined } {
    const start = statement.context?.extensions[EXTENSION_URL_LEARNING_OBJECT_ID]?.length
      ?? xerteUrlLenght;

    if (statement.object.id !== undefined) {
      const position1 = statement.object.id.indexOf('/', start);
      if (position1 >= 0) {
        const position2 = statement.object.id.indexOf('/', start + position1);
        if (position2 >= 0) {
          const id = statement.object.id.substring(0, position2);
          return interactionHashes.get(id) ?? { index: -1, childIndex: undefined };
        }
        return interactionHashes.get(statement.object.id) ?? { index: -1, childIndex: undefined };
      }
    }
    return { index: -1, childIndex: undefined };
  }
}

/**
 * Get the inverse functional identifier of a statement. We will use the mbox_sha1sum if
 * it exists, otherwise we will use the mbox.
 *
 * @param statement - A Statement object
 */
export function getInverseFunctionalIdentifier(statement: Statement): InverseFunctionalIdentifier {
  if (statement.actor.objectType === 'Group') {
    return new InverseFunctionalIdentifier({ account: statement.actor.account });
  }
  if (statement.actor.mbox_sha1sum !== undefined) {
    return new InverseFunctionalIdentifier({ mboxSha1Sum: statement.actor.mbox_sha1sum });
  }
  if (statement.actor.mbox !== undefined) {
    return new InverseFunctionalIdentifier({ mbox: statement.actor.mbox });
  }
  throw new Error('No inverse functional identifier found');
}
