import { Actor } from './statement';
import { XTCorrectResult } from './xt-correct-result';
import { XTInteractionType } from './xt-interaction-type';
import { XTScoreMode } from './xt-score-mode';

type TrackingMode = 'full' | 'minimal' | 'none';
type Mode = 'normal';
type LearningObjectType = 'interactive' | 'pages only';

export type MatchOption = {
  source: string;
  target: string;
  result?: boolean;
};

type ExternalTrackingInteraction = {
  id: string;
  page_nr: number;
  ia_nr: number,
  ia_type: XTInteractionType,
  ia_name: string;
  start: Date;
  end: Date;
  count: number
  duration: number;
  nrinteractions: number;
  weighting: number;
  score: number;
  grouping: string;
  context: string;
  correctAnswers: any[];
  correctOptions: MatchOption[] | any[];
  learnerAnswers: any;
  learnerOptions: MatchOption[] | any[];
  result: XTCorrectResult;
  feedback: string;
};

export type ExternalTrackingState = {
  category: string;
  completedPages: boolean[];
  course: string;
  coursename: string;
  currentid: string;
  currentpageid: string;
  debug: boolean;
  embedded: boolean;
  finished: boolean;
  forcetrackingmode: string; // boolean
  group: Actor;
  initialised: boolean;
  interactions: ExternalTrackingInteraction[];
  language: string;
  lo_completed: number;
  lo_passed: number;
  lo_type: LearningObjectType;
  mode: Mode;
  module: string;
  modulename: string;
  nrpages: number;
  pageHistory: any[];
  page_timeout: number;
  pagesViewed: number[];
  prevVerb: string;
  resume: boolean;
  resumedSessions: any[];
  scoremode: XTScoreMode;
  sessionId: string;
  start: Date;
  templateId: string;
  templateName: string;
  toCompletePages: number[];
  trackingmode: TrackingMode;
  videostart: Date;
};

export type TrackingInteraction = {
  id: string;
  pageNr: number;
  iaNr: number,
  iaType: XTInteractionType,
  iaName: string;
  start: Date;
  end: Date;
  count: number
  duration: number;
  nrInteractions: number;
  weighting: number;
  score: number;
  grouping: string;
  context: string;
  correctAnswers: any[];
  correctOptions: MatchOption[] | any[];
  learnerAnswers: any;
  learnerOptions: MatchOption[] | any[];
  result: XTCorrectResult;
  feedback: string;
};

export type TrackingState = {
  category: string;
  completedPages: boolean[];
  course: string;
  courseName: string;
  currentId: string;
  currentPageId: string;
  debug: boolean;
  embedded: boolean;
  finished: boolean;
  forceTrackingMode: boolean;
  group: Actor;
  initialised: boolean;
  interactions: TrackingInteraction[];
  language: string;
  loCompleted: number;
  loPassed: number;
  loType: LearningObjectType;
  mode: Mode;
  module: string;
  moduleName: string;
  nrPages: number;
  pageHistory: any[];
  pageTimeout: number;
  pagesViewed: number[];
  prevVerb: string;
  resume: boolean;
  resumedSessions: any[];
  scoreMode: XTScoreMode;
  sessionId: string;
  start: Date;
  templateId: string;
  templateName: string;
  toCompletePages: number[];
  trackingMode: TrackingMode;
  videoStart: Date;
};

function toTrackingInteraction(
  externalTrackingInteraction: ExternalTrackingInteraction,
): TrackingInteraction {
  return {
    id: externalTrackingInteraction.id,
    pageNr: externalTrackingInteraction.page_nr,
    iaNr: externalTrackingInteraction.ia_nr,
    iaType: externalTrackingInteraction.ia_type,
    iaName: externalTrackingInteraction.ia_name,
    start: externalTrackingInteraction.start,
    end: externalTrackingInteraction.end,
    count: externalTrackingInteraction.count,
    duration: externalTrackingInteraction.duration,
    nrInteractions: externalTrackingInteraction.nrinteractions,
    weighting: externalTrackingInteraction.weighting,
    score: externalTrackingInteraction.score,
    grouping: externalTrackingInteraction.grouping,
    context: externalTrackingInteraction.context,
    correctAnswers: externalTrackingInteraction.correctAnswers,
    correctOptions: externalTrackingInteraction.correctOptions,
    learnerAnswers: externalTrackingInteraction.learnerAnswers,
    learnerOptions: externalTrackingInteraction.learnerOptions,
    result: externalTrackingInteraction.result,
    feedback: externalTrackingInteraction.feedback,
  };
}

export function toTrackingState(externalTrackingState: ExternalTrackingState): TrackingState {
  return {
    category: externalTrackingState.category,
    completedPages: externalTrackingState.completedPages,
    course: externalTrackingState.course,
    courseName: externalTrackingState.coursename,
    currentId: externalTrackingState.currentid,
    currentPageId: externalTrackingState.currentpageid,
    debug: externalTrackingState.debug,
    embedded: externalTrackingState.embedded,
    finished: externalTrackingState.finished,
    forceTrackingMode: externalTrackingState.forcetrackingmode === 'true',
    group: externalTrackingState.group,
    initialised: externalTrackingState.initialised,
    interactions: externalTrackingState.interactions.map(
      (interaction) => toTrackingInteraction(interaction),
    ),
    language: externalTrackingState.language,
    loCompleted: externalTrackingState.lo_completed,
    loPassed: externalTrackingState.lo_passed,
    loType: externalTrackingState.lo_type,
    mode: externalTrackingState.mode,
    module: externalTrackingState.module,
    moduleName: externalTrackingState.modulename,
    nrPages: externalTrackingState.nrpages,
    pageHistory: externalTrackingState.pageHistory,
    pageTimeout: externalTrackingState.page_timeout,
    pagesViewed: externalTrackingState.pagesViewed,
    prevVerb: externalTrackingState.prevVerb,
    resume: externalTrackingState.resume,
    resumedSessions: externalTrackingState.resumedSessions,
    scoreMode: externalTrackingState.scoremode,
    sessionId: externalTrackingState.sessionId,
    start: externalTrackingState.start,
    templateId: externalTrackingState.templateId,
    templateName: externalTrackingState.templateName,
    toCompletePages: externalTrackingState.toCompletePages,
    trackingMode: externalTrackingState.trackingmode,
    videoStart: externalTrackingState.videostart,
  };
}
