import GroupedDataLearningObject from '../grouped-data-learning-object/grouped-data-learning-object';
import {
  EXTENSION_URL_COURSE,
  EXTENSION_URL_LEARNING_OBJECT_ID,
  EXTENSION_URL_LEARNING_OBJECT_TITLE,
  EXTENSION_URL_MODULE,
} from '../types/extension';
import { Statement } from '../types/statement';
import { VERB_URL_LAUNCHED } from '../types/verb';

export default function initiateLearningObjectsFromStatements(
  statements: Statement[],
): GroupedDataLearningObject[] {
  const learningObjectUris: Map<string, number> = new Map();
  const learningObjectCourseModule: Map<string, number> = new Map();
  const learningObjects: GroupedDataLearningObject[] = [];

  statements.forEach((statement) => {
    if (statement.verb.id === VERB_URL_LAUNCHED) {
      // If the extension is set, use it to get the learning object ID, if not, use the objectId.
      const objectId = statement.context?.extensions[EXTENSION_URL_LEARNING_OBJECT_ID]
        ?? statement.object.id;

      const learningObjectTitle = statement.context?.extensions[
        EXTENSION_URL_LEARNING_OBJECT_TITLE
      ];

      if (learningObjectTitle !== undefined) {
        // If the object id is already known, update the learning object.
        const uriIdx = learningObjectUris.get(objectId);
        if (uriIdx !== undefined) {
          const lo = learningObjects[uriIdx];
          lo?.names.add(learningObjectTitle);
          lo?.urls.add(objectId);
          return;
        }

        // If the course and the module are already known, update the learning object
        // and add the url.
        const course = statement.context?.extensions[EXTENSION_URL_COURSE];
        const module = statement.context?.extensions[EXTENSION_URL_MODULE];

        if (module !== undefined && course !== undefined) {
          const courseIdx = learningObjectCourseModule.get(`course: ${course}, module: ${module}`);
          if (courseIdx !== undefined) {
            const lo = learningObjects[courseIdx];
            lo?.names.add(learningObjectTitle);
            lo?.urls.add(objectId);

            learningObjectUris.set(objectId, courseIdx);
            return;
          }
        }

        // If the learning object is not already known, add it.
        const newLen = learningObjects.push(new GroupedDataLearningObject(
          {
            url: objectId,
            course,
            module,
            names: new Set([learningObjectTitle]),
            urls: new Set([objectId]),
          },
        ));
        learningObjectUris.set(objectId, newLen - 1);
        if (module !== undefined && course !== undefined) {
          learningObjectCourseModule.set(`course: ${course}, module: ${module}`, newLen - 1);
        }
      }
    }
  });
  return learningObjects;
}
