import { IGroupedDataLearningObject } from '../interfaces/IGroupedDataLearningObject';

export default class GroupedDataLearningObject implements IGroupedDataLearningObject {
  /** The course of the learning object */
  public get course(): string | undefined {
    return this.#course;
  }

  /** The module of the learning object */
  public get module(): string | undefined {
    return this.#module;
  }

  /** The names of the learning object */
  public get names(): Set<string> {
    return this.#names;
  }

  /** The passing percentage of the learning object */
  public get passingPercentage(): number | undefined {
    return this.#passingPercentage;
  }

  /** The URL of the learning object */
  public get url(): string {
    return this.#url;
  }

  /** The URLs of the learning object */
  public get urls(): Set<string> {
    return this.#urls;
  }

  #course: string | undefined;

  #module: string | undefined;

  #names: Set<string>;

  #passingPercentage: number | undefined;

  #url: string;

  #urls: Set<string>;

  /**
   * Constructor for GroupedDataLearningObject
   *
   * @param course - The course of the learning object
   * @param module - The module of the learning object
   * @param names - The names of the learning object
   * @param passingPercentage - The passing percentage of the learning object
   * @param url - The URL of the learning object
   * @param urls - The URLs of the learning object
   */
  constructor({
    course, module, names, passingPercentage, url, urls,
  }: {
    course?: string;
    module?: string;
    names: Set<string>;
    passingPercentage?: number;
    url: string;
    urls: Set<string>;
  }) {
    this.#course = course;
    this.#module = module;
    this.#names = names;
    this.#passingPercentage = passingPercentage;
    this.#url = url;
    this.#urls = urls;
  }
}
